const c = $input.first().json ?? {};

const errors = [];

const githubUsername =
  String(c.github_username ?? '').trim();

const apiMode =
  String(c.api_mode ?? '').trim().toLowerCase();

const maxPages = Number(c.max_pages);
const timeoutMs = Number(c.timeout_ms);

if (!githubUsername) {
  errors.push('github_username is required');
}

if (githubUsername.length > 39) {
  errors.push('github_username must have at most 39 characters');
}

if (
  githubUsername &&
  !/^[A-Za-z0-9-]+$/.test(githubUsername)
) {
  errors.push(
    'github_username may contain only letters, numbers and hyphens'
  );
}

if (
  githubUsername.startsWith('-') ||
  githubUsername.endsWith('-')
) {
  errors.push(
    'github_username cannot start or end with a hyphen'
  );
}

if (
  !Number.isInteger(maxPages) ||
  maxPages < 1 ||
  maxPages > 100
) {
  errors.push('max_pages must be an integer between 1 and 100');
}

if (
  !Number.isFinite(timeoutMs) ||
  timeoutMs <= 0
) {
  errors.push('timeout_ms must be positive');
}

if (!['live', 'simulator'].includes(apiMode)) {
  errors.push('api_mode must be live or simulator');
}

const rawInput =
  apiMode === 'live'
    ? c.live_base_url
    : c.simulator_base_url;

if (!rawInput) {
    errors.push('API base URL is missing or undefined');
}
// Sanitiza removendo aspas externas, espaços e caracteres invisíveis/de controle
const rawBaseUrl = String(rawInput ?? '')
  .trim()
  .replace(/^["']|["']$/g, '')
  .replace(/[\u0000-\u001F\u007F-\u009F\u200B-\u200D\uFEFF]/g, '');

let apiBaseUrl = null;

try {
  console.log("VALOR RECEBIDO:", JSON.stringify(rawBaseUrl));
  const urlPattern = /^(https?):\/\/[^\s/$.?#].[^\s]*$/i;
    if (!urlPattern.test(rawBaseUrl)) {
        throw new Error("Invalid URL format");
    }

    if (apiMode === 'live' && !rawBaseUrl.startsWith('https:')) {
        errors.push('live API base URL must use HTTPS');
    }

    apiBaseUrl = rawBaseUrl.replace(/\/+$/, '');
} catch (err) {
    errors.push('API base URL is invalid: ' + err.message);
}

if (errors.length > 0) {
  throw new Error(
    'P01_SAFE_ERROR:' +
    JSON.stringify({
      stage: 'configuration',
      category: 'validation',
      attempt: 0,
      retryable: false,
      message: errors.join('; ')
    })
  );
}

return [
  {
    json: {
      github_username: githubUsername,
      api_mode: apiMode,
      api_base_url: apiBaseUrl,

      api_version:
        String(c.api_version ?? '2026-03-10'),

      max_pages: maxPages,
      timeout_ms: timeoutMs,

      max_retries:
        Number.isInteger(Number(c.max_retries))
          ? Number(c.max_retries)
          : 3,

      stale_after_minutes:
        Number.isInteger(
          Number(c.stale_after_minutes)
        )
          ? Number(c.stale_after_minutes)
          : 120,

      simulator_scenario:
        String(
          c.simulator_scenario ?? 'happy'
        ),

      workflow_execution_id:
        String(c.workflow_execution_id ?? '')
    }
  }
];

const run = $input.first().json;
const cfg = $('Validate Configuration').first().json;

return [
  {
    json: {
      run_id: Number(run.id),

      github_username: String(cfg.github_username),

      api_mode: String(cfg.api_mode),

      api_base_url: String(cfg.api_base_url),

      api_version: String(
        cfg.api_version ?? '2026-03-10'
      ),

      max_pages: Number(cfg.max_pages),

      timeout_ms: Number(cfg.timeout_ms),

      // Política fixa do projeto:
      // tentativa original + 3 retries
      max_retries: 3,

      simulator_scenario: String(
        cfg.simulator_scenario ?? 'happy'
      ),

      stage: 'profile',

      request_kind: 'profile',

      // tentativa ORIGINAL
      attempt: 0
    }
  }
];

const x = $input.first().json;

return [
  {
    json: {
      ...x,

      stage: 'profile',
      request_kind: 'profile'
    }
  }
];

// Resposta do HTTP Request
const response = $json ?? {};

// Contexto que entrou no request atual.
// Usamos .item para manter a associação correta inclusive
// quando o node executar novamente durante retries.
const ctx =
  $('Prepare Profile Request').item.json;


// --------------------------------------------------
// Helpers
// --------------------------------------------------

function getHeader(headers, name) {
  if (!headers || typeof headers !== 'object') {
    return null;
  }

  const wanted = name.toLowerCase();

  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() === wanted) {
      return value;
    }
  }

  return null;
}

function integerOrNull(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const n = Number(value);

  return Number.isInteger(n)
    ? n
    : null;
}


// --------------------------------------------------
// Response
// --------------------------------------------------

const status =
  Number(response.statusCode ?? 0);

const body =
  response.body ?? null;

const headers =
  response.headers ?? {};


// --------------------------------------------------
// Headers permitidos
// --------------------------------------------------

const githubRequestId =
  getHeader(
    headers,
    'x-github-request-id'
  );

const rateLimitLimit =
  integerOrNull(
    getHeader(
      headers,
      'x-ratelimit-limit'
    )
  );

const rateLimitRemaining =
  integerOrNull(
    getHeader(
      headers,
      'x-ratelimit-remaining'
    )
  );

const rateLimitResetEpoch =
  integerOrNull(
    getHeader(
      headers,
      'x-ratelimit-reset'
    )
  );

const retryAfter =
  getHeader(
    headers,
    'retry-after'
  );


// --------------------------------------------------
// Reset timestamp
// --------------------------------------------------

let rateLimitResetAt = null;

if (rateLimitResetEpoch !== null) {
  const date =
    new Date(
      rateLimitResetEpoch * 1000
    );

  if (!Number.isNaN(date.getTime())) {
    rateLimitResetAt =
      date.toISOString();
  }
}


// --------------------------------------------------
// Mensagem GitHub
// --------------------------------------------------

let githubMessage = '';

if (
  body &&
  typeof body === 'object' &&
  !Array.isArray(body)
) {
  githubMessage =
    String(body.message ?? '');
}


// --------------------------------------------------
// Identificar secondary rate limit
// --------------------------------------------------

const secondaryRateLimit =
  (
    status === 403 ||
    status === 429
  ) &&
  (
    retryAfter !== null ||
    /secondary rate limit|abuse/i.test(
      githubMessage
    )
  );


// --------------------------------------------------
// Classificação
// --------------------------------------------------

let classification =
  'unexpected_status';

let category =
  'unexpected';

let retryable =
  false;

let rateLimitKind =
  null;


// SUCCESS

if (
  status >= 200 &&
  status <= 299
) {
  classification = 'success';
  category = null;
  retryable = false;
}


// 401

else if (status === 401) {
  classification =
    'authentication_error';

  category =
    'authentication';

  retryable = false;
}


// RATE LIMIT

else if (
  status === 429 ||
  (
    status === 403 &&
    rateLimitRemaining === 0
  ) ||
  secondaryRateLimit
) {
  classification =
    'rate_limited';

  category =
    'rate_limit';

  retryable = true;

  rateLimitKind =
    secondaryRateLimit
      ? 'secondary'
      : 'primary';
}


// 403 comum

else if (status === 403) {
  classification =
    'authorization_error';

  category =
    'authorization';

  retryable = false;
}


// 5xx

else if (
  status >= 500 &&
  status <= 599
) {
  classification =
    'retryable_server_error';

  category =
    'github_server';

  retryable = true;
}


// --------------------------------------------------
// Saída SEGURA
// --------------------------------------------------
//
// Não retornamos headers completos.
// --------------------------------------------------

return {
  json: {
    ...ctx,

    http_status:
      status || null,

    github_request_id:
      githubRequestId,

    rate_limit_limit:
      rateLimitLimit,

    rate_limit_remaining:
      rateLimitRemaining,

    rate_limit_reset_at:
      rateLimitResetAt,

    retry_after:
      retryAfter,

    rate_limit_kind:
      rateLimitKind,

    classification,

    category,

    retryable,

    response_body:
      body
  }
};

const x = $input.first().json;

const body =
  x.response_body;


// --------------------------------------------------
// Helpers
// --------------------------------------------------

function nullableString(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const text =
    String(value);

  return text.trim() === ''
    ? null
    : text;
}


function requiredString(
  value,
  field,
  errors
) {
  const normalized =
    nullableString(value);

  if (normalized === null) {
    errors.push(
      `missing required field: ${field}`
    );
  }

  return normalized;
}


function nonNegativeInteger(
  value,
  field,
  errors
) {
  const n =
    Number(value ?? 0);

  if (
    !Number.isInteger(n) ||
    n < 0
  ) {
    errors.push(
      `invalid non-negative integer: ${field}`
    );

    return 0;
  }

  return n;
}


function isoOrNull(
  value,
  field,
  errors
) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const date =
    new Date(value);

  if (
    Number.isNaN(
      date.getTime()
    )
  ) {
    errors.push(
      `invalid timestamp: ${field}`
    );

    return null;
  }

  return date.toISOString();
}


// --------------------------------------------------
// Body
// --------------------------------------------------

const errors = [];

if (
  !body ||
  typeof body !== 'object' ||
  Array.isArray(body)
) {
  errors.push(
    'profile response must be an object'
  );
}


// --------------------------------------------------
// Obrigatórios
// --------------------------------------------------

let githubUserId = null;

if (
  body?.id === null ||
  body?.id === undefined
) {
  errors.push(
    'missing required field: id'
  );
}
else {
  githubUserId =
    String(body.id);
}


const login =
  requiredString(
    body?.login,
    'login',
    errors
  );

const htmlUrl =
  requiredString(
    body?.html_url,
    'html_url',
    errors
  );


// --------------------------------------------------
// Counters
// --------------------------------------------------

const publicRepos =
  nonNegativeInteger(
    body?.public_repos,
    'public_repos',
    errors
  );

const followers =
  nonNegativeInteger(
    body?.followers,
    'followers',
    errors
  );

const following =
  nonNegativeInteger(
    body?.following,
    'following',
    errors
  );


// --------------------------------------------------
// Datas
// --------------------------------------------------

const githubCreatedAt =
  isoOrNull(
    body?.created_at,
    'created_at',
    errors
  );

const githubUpdatedAt =
  isoOrNull(
    body?.updated_at,
    'updated_at',
    errors
  );


// --------------------------------------------------
// Falha
// --------------------------------------------------

if (errors.length > 0) {
  return [
    {
      json: {
        valid: false,

        failure: {
          run_id:
            x.run_id,

          stage:
            'profile',

          node_name:
            '05 | Normalize Profile',

          category:
            'validation',

          error_code:
            'profile_validation_error',

          http_status:
            x.http_status,

          github_request_id:
            x.github_request_id,

          rate_limit_limit:
            x.rate_limit_limit,

          rate_limit_remaining:
            x.rate_limit_remaining,

          rate_limit_reset_at:
            x.rate_limit_reset_at,

          attempt:
            x.attempt,

          retryable:
            false,

          safe_message:
            errors.join('; ')
        }
      }
    }
  ];
}


// --------------------------------------------------
// SUCESSO
//
// Campos desconhecidos são descartados.
// --------------------------------------------------

return [
  {
    json: {
      valid: true,

      run_id:
        x.run_id,

      github_username:
        x.github_username,

      api_mode:
        x.api_mode,

      api_base_url:
        x.api_base_url,

      api_version:
        x.api_version,

      max_pages:
        x.max_pages,

      timeout_ms:
        x.timeout_ms,

      max_retries:
        x.max_retries,

      simulator_scenario:
        x.simulator_scenario,

      github_request_id:
        x.github_request_id,

      rate_limit_limit:
        x.rate_limit_limit,

      rate_limit_remaining:
        x.rate_limit_remaining,

      rate_limit_reset_at:
        x.rate_limit_reset_at,

      profile: {
        github_user_id:
          githubUserId,

        login,

        name:
          nullableString(
            body.name
          ),

        bio:
          nullableString(
            body.bio
          ),

        company:
          nullableString(
            body.company
          ),

        location:
          nullableString(
            body.location
          ),

        blog:
          nullableString(
            body.blog
          ),

        html_url:
          htmlUrl,

        avatar_url:
          nullableString(
            body.avatar_url
          ),

        public_repos:
          publicRepos,

        followers,

        following,

        github_created_at:
          githubCreatedAt,

        github_updated_at:
          githubUpdatedAt
      }
    }
  }
];

return [
  {
    json:
      $input.first().json.failure
  }
];

const context =
  $input.first().json.context;

return [
  {
    json:
      typeof context === 'string'
        ? JSON.parse(context)
        : context
  }
];

const x =
  $input.first().json;

const page =
  Number(x.page);

if (
  !Number.isInteger(page) ||
  page < 1
) {
  throw new Error(
    'Invalid internal repository page'
  );
}

return [
  {
    json: {
      ...x,
      stage: 'repositories',
      request_kind: 'repositories',
      page
    }
  }
];

const response =
  $json ?? {};

const ctx =
  $('Prepare Repository Request').item.json;


function getHeader(headers, name) {
  if (!headers || typeof headers !== 'object') {
    return null;
  }

  const wanted =
    name.toLowerCase();

  for (
    const [key, value]
    of Object.entries(headers)
  ) {
    if (
      key.toLowerCase() === wanted
    ) {
      return value;
    }
  }

  return null;
}


function integerOrNull(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const n =
    Number(value);

  return Number.isInteger(n)
    ? n
    : null;
}


const status =
  Number(
    response.statusCode ?? 0
  );

const body =
  response.body ?? null;

const headers =
  response.headers ?? {};


const githubRequestId =
  getHeader(
    headers,
    'x-github-request-id'
  );

const rateLimitLimit =
  integerOrNull(
    getHeader(
      headers,
      'x-ratelimit-limit'
    )
  );

const rateLimitRemaining =
  integerOrNull(
    getHeader(
      headers,
      'x-ratelimit-remaining'
    )
  );

const resetEpoch =
  integerOrNull(
    getHeader(
      headers,
      'x-ratelimit-reset'
    )
  );

const retryAfter =
  getHeader(
    headers,
    'retry-after'
  );

const link =
  getHeader(
    headers,
    'link'
  );


let rateLimitResetAt =
  null;

if (resetEpoch !== null) {
  const date =
    new Date(
      resetEpoch * 1000
    );

  if (!Number.isNaN(date.getTime())) {
    rateLimitResetAt =
      date.toISOString();
  }
}


let githubMessage = '';

if (
  body &&
  typeof body === 'object' &&
  !Array.isArray(body)
) {
  githubMessage =
    String(body.message ?? '');
}


const secondaryRateLimit =
  (
    status === 403 ||
    status === 429
  )
  &&
  (
    retryAfter !== null ||
    /secondary rate limit|abuse/i
      .test(githubMessage)
  );


let classification =
  'unexpected_status';

let category =
  'unexpected';

let retryable =
  false;

let rateLimitKind =
  null;


if (
  status >= 200 &&
  status <= 299
) {
  classification =
    'success';

  category =
    null;
}


else if (status === 401) {
  classification =
    'authentication_error';

  category =
    'authentication';
}


else if (
  status === 429 ||
  (
    status === 403 &&
    rateLimitRemaining === 0
  ) ||
  secondaryRateLimit
) {
  classification =
    'rate_limited';

  category =
    'rate_limit';

  retryable =
    true;

  rateLimitKind =
    secondaryRateLimit
      ? 'secondary'
      : 'primary';
}


else if (status === 403) {
  classification =
    'authorization_error';

  category =
    'authorization';
}


else if (
  status >= 500 &&
  status <= 599
) {
  classification =
    'retryable_server_error';

  category =
    'github_server';

  retryable =
    true;
}


return {
  json: {
    ...ctx,

    http_status:
      status || null,

    github_request_id:
      githubRequestId,

    rate_limit_limit:
      rateLimitLimit,

    rate_limit_remaining:
      rateLimitRemaining,

    rate_limit_reset_at:
      rateLimitResetAt,

    retry_after:
      retryAfter,

    rate_limit_kind:
      rateLimitKind,

    link_header:
      link,

    classification,

    category,

    retryable,

    response_body:
      body
  }
};

const err =
  $json ?? {};

const ctx =
  $('Prepare Repository Request')
    .item.json;

const rawMessage =
  String(
    err.message ??
    err.error?.message ??
    ''
  );

const isTimeout =
  /timeout|timed out|etimedout|esockettimedout|aborted/i
    .test(rawMessage);

return {
  json: {
    ...ctx,

    classification:
      isTimeout
        ? 'timeout'
        : 'network_error',

    category:
      isTimeout
        ? 'timeout'
        : 'network',

    retryable:
      true,

    http_status:
      null,

    github_request_id:
      null,

    rate_limit_limit:
      null,

    rate_limit_remaining:
      null,

    rate_limit_reset_at:
      null,

    retry_after:
      null,

    safe_transport_message:
      isTimeout
        ? 'GitHub repository request timed out'
        : 'GitHub repository network request failed'
  }
};

const x =
  $input.first().json;

const body =
  x.response_body;

const errors = [];


// --------------------------------------------------
// Helpers
// --------------------------------------------------

function nullableString(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const text =
    String(value);

  return text.trim() === ''
    ? null
    : text;
}


function requiredString(
  value,
  field,
  repoIndex
) {
  const text =
    nullableString(value);

  if (text === null) {
    errors.push(
      `repository[${repoIndex}] missing ${field}`
    );
  }

  return text;
}


function nonNegativeInteger(
  value,
  field,
  repoIndex
) {
  const n =
    Number(value ?? 0);

  if (
    !Number.isInteger(n) ||
    n < 0
  ) {
    errors.push(
      `repository[${repoIndex}] invalid ${field}`
    );

    return 0;
  }

  return n;
}


function booleanValue(
  value,
  field,
  repoIndex
) {
  if (
    value === undefined ||
    value === null
  ) {
    return false;
  }

  if (typeof value !== 'boolean') {
    errors.push(
      `repository[${repoIndex}] invalid ${field}`
    );

    return false;
  }

  return value;
}


function isoOrNull(
  value,
  field,
  repoIndex
) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const date =
    new Date(value);

  if (
    Number.isNaN(
      date.getTime()
    )
  ) {
    errors.push(
      `repository[${repoIndex}] invalid ${field}`
    );

    return null;
  }

  return date.toISOString();
}


// --------------------------------------------------
// Body deve ser array
// --------------------------------------------------

if (!Array.isArray(body)) {
  return [
    {
      json: {
        valid: false,

        failure: {
          run_id:
            x.run_id,

          stage:
            'repositories',

          node_name:
            '06 | Normalize Repository Page',

          category:
            'validation',

          error_code:
            'repository_page_validation_error',

          http_status:
            x.http_status,

          github_request_id:
            x.github_request_id,

          attempt:
            x.attempt,

          retryable:
            false,

          safe_message:
            'Repository response body is not an array'
        }
      }
    }
  ];
}


// --------------------------------------------------
// Normalize
// --------------------------------------------------

const repositories =
  body.map(
    (repo, index) => {

      let githubRepoId = null;

      if (
        repo?.id === undefined ||
        repo?.id === null
      ) {
        errors.push(
          `repository[${index}] missing id`
        );
      }
      else {
        githubRepoId =
          String(repo.id);
      }


      const topics =
        repo?.topics === undefined ||
        repo?.topics === null
          ? []
          : repo.topics;

      if (!Array.isArray(topics)) {
        errors.push(
          `repository[${index}] invalid topics`
        );
      }


      return {
        github_repo_id:
          githubRepoId,

        owner_login:
          requiredString(
            repo?.owner?.login,
            'owner.login',
            index
          ),

        name:
          requiredString(
            repo?.name,
            'name',
            index
          ),

        full_name:
          requiredString(
            repo?.full_name,
            'full_name',
            index
          ),

        description:
          nullableString(
            repo?.description
          ),

        html_url:
          requiredString(
            repo?.html_url,
            'html_url',
            index
          ),

        language:
          nullableString(
            repo?.language
          ),

        topics:
          Array.isArray(topics)
            ? topics.map(String)
            : [],

        visibility:
          requiredString(
            repo?.visibility,
            'visibility',
            index
          ),

        default_branch:
          nullableString(
            repo?.default_branch
          ),

        fork:
          booleanValue(
            repo?.fork,
            'fork',
            index
          ),

        archived:
          booleanValue(
            repo?.archived,
            'archived',
            index
          ),

        disabled:
          booleanValue(
            repo?.disabled,
            'disabled',
            index
          ),

        stargazers_count:
          nonNegativeInteger(
            repo?.stargazers_count,
            'stargazers_count',
            index
          ),

        watchers_count:
          nonNegativeInteger(
            repo?.watchers_count,
            'watchers_count',
            index
          ),

        forks_count:
          nonNegativeInteger(
            repo?.forks_count,
            'forks_count',
            index
          ),

        open_issues_count:
          nonNegativeInteger(
            repo?.open_issues_count,
            'open_issues_count',
            index
          ),

        size:
          nonNegativeInteger(
            repo?.size,
            'size',
            index
          ),

        github_created_at:
          isoOrNull(
            repo?.created_at,
