const x =
  $input.first().json;

const attempt =
  Number(x.attempt ?? 0);

let delaySeconds =
  null;

let delaySource =
  null;


// --------------------------------------------------
// 1. Retry-After TEM PRIORIDADE
// --------------------------------------------------

if (
  x.retry_after !== null &&
  x.retry_after !== undefined &&
  x.retry_after !== ''
) {
  const numeric =
    Number(x.retry_after);

  if (
    Number.isFinite(numeric) &&
    numeric >= 0
  ) {
    delaySeconds =
      Math.ceil(numeric);

    delaySource =
      'retry_after';
  }
  else {
    const date =
      new Date(
        x.retry_after
      );

    if (
      !Number.isNaN(
        date.getTime()
      )
    ) {
      delaySeconds =
        Math.max(
          0,
          Math.ceil(
            (
              date.getTime()
              -
              Date.now()
            )
            / 1000
          )
        );

      delaySource =
        'retry_after_date';
    }
  }
}


// --------------------------------------------------
// 2. Primary rate limit
// --------------------------------------------------

if (
  delaySeconds === null &&
  x.category === 'rate_limit' &&
  Number(x.rate_limit_remaining) === 0 &&
  x.rate_limit_reset_at
) {
  const reset =
    new Date(
      x.rate_limit_reset_at
    );

  if (
    !Number.isNaN(
      reset.getTime()
    )
  ) {
    delaySeconds =
      Math.max(
        1,
        Math.ceil(
          (
            reset.getTime()
            -
            Date.now()
          )
          / 1000
        )
        + 1
      );

    delaySource =
      'rate_limit_reset';
  }
}


// --------------------------------------------------
// 3. Secondary limit sem Retry-After
// --------------------------------------------------

if (
  delaySeconds === null &&
  x.category === 'rate_limit'
) {
  const secondaryDelays =
    [
      60,
      120,
      240
    ];

  delaySeconds =
    secondaryDelays[
      Math.min(
        attempt,
        secondaryDelays.length - 1
      )
    ];

  delaySource =
    'secondary_rate_limit';
}


// --------------------------------------------------
// 4. Timeout / network / 5xx
// --------------------------------------------------

if (delaySeconds === null) {
  const transientDelays =
    [
      5,
      15,
      45
    ];

  delaySeconds =
    transientDelays[
      Math.min(
        attempt,
        transientDelays.length - 1
      )
    ];

  delaySource =
    'transient_error';
}


